local PrintingPressMaker = {}
local PRODUCTS = {
    simple_wood_printing_press = { name = "Preprosta lesena tiskarska stiskalnica", woodCost = 5, ironCost = 2, time = 8, cost = 300, science = 30, happiness = 2, description = "Preprosta lesena tiskarska stiskalnica za tisk." },
    iron_reinforced_press = { name = "Železnookrepljena tiskarska stiskalnica", woodCost = 4, ironCost = 3, time = 11, cost = 680, science = 45, happiness = 2, prestige = 2, description = "Železnookrepljena tiskarska stiskalnica za trgovce." },
    silver_geared_press = { name = "Srebrnozobčana tiskarska stiskalnica", woodCost = 4, silverCost = 1, ironCost = 3, time = 15, cost = 1500, science = 60, happiness = 3, prestige = 6, description = "Srebrnozobčana tiskarska stiskalnica za plemiče." },
    gold_trimmed_press = { name = "Zlatookrasna tiskarska stiskalnica", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 3, time = 19, cost = 3400, science = 75, happiness = 4, prestige = 14, description = "Zlatookrasna tiskarska stiskalnica za visoke plemiče." },
    jewel_set_press = { name = "Draguljasta tiskarska stiskalnica", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 3, jewelCost = 1, time = 23, cost = 7200, science = 88, happiness = 6, prestige = 27, description = "Tiskarska stiskalnica z draguljem za visoko plemstvo." },
    royal_grand_printing_press = { name = "Kraljevski veliki tiskarska stiskalnica", woodCost = 6, goldCost = 2, silverCost = 2, ironCost = 3, jewelCost = 2, pearlCost = 2, time = 30, cost = 15000, science = 95, happiness = 12, prestige = 58, description = "Velika kraljevska tiskarska stiskalnica z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    press_workshop = { name = "Tiskarska delavnica", cost = { gold = 320, wood = 180, stone = 160, iron = 8 }, upkeep = 7, qualityBonus = 5 },
    printing_loft = { name = "Tiskarska podstrešje", cost = { gold = 1200, wood = 320, stone = 320, silver = 6, iron = 8 }, upkeep = 28, qualityBonus = 18 },
    master_press_atelier = { name = "Mojstrski tiskarski atelje", cost = { gold = 3000, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 70, qualityBonus = 30 },
    royal_printing_palace = { name = "Kraljevska tiskarska palača", cost = { gold = 13000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 260, qualityBonus = 55, prestigeBonus = 50 },
}
PrintingPressMaker.woodStock = 22; PrintingPressMaker.ironStock = 14; PrintingPressMaker.silverStock = 6; PrintingPressMaker.goldStock = 6; PrintingPressMaker.jewelStock = 4; PrintingPressMaker.pearlStock = 4
PrintingPressMaker.productStock = {}; PrintingPressMaker.buildings = {}; PrintingPressMaker.maker = nil; PrintingPressMaker.activeMaking = {}; PrintingPressMaker.totalProducts = 0; PrintingPressMaker.dayTimer = 0
function PrintingPressMaker.init() PrintingPressMaker.woodStock=22; PrintingPressMaker.ironStock=14; PrintingPressMaker.silverStock=6; PrintingPressMaker.goldStock=6; PrintingPressMaker.jewelStock=4; PrintingPressMaker.pearlStock=4; PrintingPressMaker.productStock={}; PrintingPressMaker.buildings={}; PrintingPressMaker.maker=nil; PrintingPressMaker.activeMaking={}; PrintingPressMaker.totalProducts=0; PrintingPressMaker.dayTimer=0; print("[PrintingPressMaker] Royal Printing Press Maker System initialized (6 products, 4 buildings)") end
function PrintingPressMaker.hireMaker(n,s) s=s or math.random(55,90); local c=640+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PrintingPressMaker.maker={name=n or ("Tiskar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tiskar najet: %s (spretnost: %d)",PrintingPressMaker.maker.name,s),"success") end; return true end
function PrintingPressMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PrintingPressMaker.build(id) local ok,e=PrintingPressMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PrintingPressMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PrintingPressMaker.getQualityBonus() local b=0; for _,bd in ipairs(PrintingPressMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PrintingPressMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and PrintingPressMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and PrintingPressMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.silverCost and PrintingPressMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PrintingPressMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PrintingPressMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PrintingPressMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PrintingPressMaker.buildings==0 then return false,"Potrebna tiskarska delavnica" end; if not PrintingPressMaker.maker then return false,"Potreben tiskar" end; return true end
function PrintingPressMaker.make(pt,qty) qty=qty or 1; local ok,e=PrintingPressMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then PrintingPressMaker.woodStock=PrintingPressMaker.woodStock-d.woodCost*qty end; if d.ironCost then PrintingPressMaker.ironStock=PrintingPressMaker.ironStock-d.ironCost*qty end; if d.silverCost then PrintingPressMaker.silverStock=PrintingPressMaker.silverStock-d.silverCost*qty end; if d.goldCost then PrintingPressMaker.goldStock=PrintingPressMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PrintingPressMaker.jewelStock=PrintingPressMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PrintingPressMaker.pearlStock=PrintingPressMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PrintingPressMaker.maker then t=math.max(1,t-math.floor(PrintingPressMaker.maker.skill/12)) end; table.insert(PrintingPressMaker.activeMaking,{id="printingpress_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gradnja: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PrintingPressMaker.completeMaking(m) local q=1.0+(PrintingPressMaker.getQualityBonus()/100); if PrintingPressMaker.maker then q=q+(PrintingPressMaker.maker.skill/140) end; q=math.min(2.5,q); PrintingPressMaker.productStock[m.productType]=(PrintingPressMaker.productStock[m.productType] or 0)+m.quantity; PrintingPressMaker.totalProducts=PrintingPressMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PrintingPressMaker.maker then PrintingPressMaker.maker.itemsMade=PrintingPressMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PrintingPressMaker.maker.skill=math.min(100,PrintingPressMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tiskarska stiskalnica izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"printingpress.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function PrintingPressMaker.update(dt) if not _G.state then return end; PrintingPressMaker.dayTimer=PrintingPressMaker.dayTimer+dt; if PrintingPressMaker.dayTimer>=30 then PrintingPressMaker.dayTimer=0; for i=#PrintingPressMaker.activeMaking,1,-1 do local m=PrintingPressMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PrintingPressMaker.completeMaking(m); table.remove(PrintingPressMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PrintingPressMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PrintingPressMaker.maker then tu=tu+18 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PrintingPressMaker.getStats() return {woodStock=PrintingPressMaker.woodStock,ironStock=PrintingPressMaker.ironStock,silverStock=PrintingPressMaker.silverStock,goldStock=PrintingPressMaker.goldStock,jewelStock=PrintingPressMaker.jewelStock,pearlStock=PrintingPressMaker.pearlStock,productStock=PrintingPressMaker.productStock,numBuildings=#PrintingPressMaker.buildings,hasMaker=PrintingPressMaker.maker~=nil,makerName=PrintingPressMaker.maker and PrintingPressMaker.maker.name or "—",makerSkill=PrintingPressMaker.maker and PrintingPressMaker.maker.skill or 0,activeMaking=#PrintingPressMaker.activeMaking,totalProducts=PrintingPressMaker.totalProducts} end
return PrintingPressMaker
